CREATE TABLE IF NOT EXISTS dim_date (date_key integer PRIMARY KEY, date date NOT NULL UNIQUE, day integer NOT NULL, day_of_week integer NOT NULL, week integer NOT NULL, month integer NOT NULL, month_name text NOT NULL, quarter integer NOT NULL, year integer NOT NULL, is_weekend boolean NOT NULL);
CREATE TABLE IF NOT EXISTS dim_user (user_key bigserial PRIMARY KEY, user_id uuid NOT NULL, full_name text NOT NULL, department text, role text, valid_from timestamptz NOT NULL, valid_to timestamptz, is_current boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS dim_user_current_uidx ON dim_user(user_id) WHERE is_current;
CREATE TABLE IF NOT EXISTS dim_department (department_key bigserial PRIMARY KEY, department_id uuid, name text NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz, is_current boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS dim_organization (organization_key bigserial PRIMARY KEY, organization_id uuid, name text NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz, is_current boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS dim_ticket_type (ticket_type_key bigserial PRIMARY KEY, ticket_type_id uuid, name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS dim_ticket_status (status_key bigserial PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL);
CREATE TABLE IF NOT EXISTS dim_development_status (status_key bigserial PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL);
CREATE TABLE IF NOT EXISTS dim_priority (priority_key integer PRIMARY KEY, name text NOT NULL);
CREATE TABLE IF NOT EXISTS dim_camera_object (camera_object_key bigserial PRIMARY KEY, camera_object_id uuid, name text NOT NULL);
CREATE TABLE IF NOT EXISTS fact_tickets (ticket_id uuid PRIMARY KEY, created_date_key integer, closed_date_key integer, organization_key bigint, department_key bigint, initiator_key bigint, executor_key bigint, ticket_type_key bigint, status_key bigint, resolution_minutes integer, sla_minutes integer, sla_breached boolean);
CREATE TABLE IF NOT EXISTS fact_development_tasks (task_id uuid PRIMARY KEY, ticket_id uuid, analyst_key bigint, developer_key bigint, status_key bigint, created_date_key integer, development_start_date_key integer, release_date_key integer, planned_hours numeric(10,2), analytics_hours numeric(10,2), development_hours numeric(10,2), total_hours numeric(10,2), subtasks_count integer, release_delay_days integer);
CREATE TABLE IF NOT EXISTS fact_work_hours (id bigserial PRIMARY KEY, task_id uuid, user_key bigint, date_key integer, hours numeric(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS fact_camera_shifts (shift_id uuid PRIMARY KEY, operator_key bigint, date_key integer, planned_hours numeric(10,2), actual_hours numeric(10,2), night_shift boolean);
CREATE TABLE IF NOT EXISTS fact_camera_violations (violation_id uuid PRIMARY KEY, author_key bigint, camera_object_key bigint, date_key integer, attachments_count integer, has_video boolean, has_photo boolean);
CREATE TABLE IF NOT EXISTS fact_sla (ticket_id uuid PRIMARY KEY, date_key integer, target_minutes integer, elapsed_minutes integer, breached boolean);
CREATE TABLE IF NOT EXISTS cube_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_type text NOT NULL CHECK (run_type IN ('bootstrap','incremental','refresh','rebuild')), status text NOT NULL DEFAULT 'running', started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, processed_records bigint NOT NULL DEFAULT 0, error text, checkpoint text);
CREATE TABLE IF NOT EXISTS analytics_checkpoints (source text PRIMARY KEY, cursor text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics_processed_events (event_id uuid NOT NULL, consumer text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_id,consumer));
CREATE TABLE IF NOT EXISTS analytics_event_log (event_id uuid PRIMARY KEY, event_type text NOT NULL, event_version integer NOT NULL, correlation_id text, occurred_at timestamptz NOT NULL, producer text NOT NULL, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
